// goal-research-brief: edge version. Runs on Cloudflare Workers and Vercel Edge (no Node APIs, no files, no shell).
// Generated by AgentSababa v4.4.3. Tools here: none.
// Left out because an edge function has no disk or shell: read_file, write_file, run_python.

const MODEL = "claude-sonnet-5-5";
const BASE_URL = "https://api.anthropic.com/v1";
const SYSTEM = "You are Goal Research Brief, an AI agent.\n\nGoal: Research a topic on the web and write a short, sourced brief with key findings and open questions.\n\nYou work in a loop: decide what is needed, call a tool when it helps, read the result, and continue until you can answer. Tools: read_file, write_file. Use a tool only when it moves the task forward, and read each result before continuing.\n\nYou run in rounds. Your notes are saved in progress.md between rounds. Make real progress each round, and call finish only when the goal is fully met.\n\nRules:\n- Be accurate. If you are unsure, say so instead of guessing.\n- Keep answers concise and well structured.\n- Never take an irreversible action unless the user asked for it.";
const MAX_TURNS = 10;
const TOKEN_BUDGET = 300000;
const MAX_TOKENS = 4096;
const ANTHROPIC = true;
const KEY_ENV = "ANTHROPIC_API_KEY";
const TOOLS = [];

// A small arithmetic parser. Edge runtimes block eval and new Function, so we cannot use them.
function calc(src) {
  const s = String(src).replace(/\s+/g, "");
  if (!/^[0-9+\-*/().%^]+$/.test(s)) throw new Error("only numbers and + - * / % ^ ( ) are allowed");
  let i = 0;
  const peek = () => s[i];
  const num = () => { const m = /^\d+(\.\d+)?/.exec(s.slice(i)); if (!m) throw new Error("expected a number at position " + i); i += m[0].length; return parseFloat(m[0]); };
  const atom = () => { if (peek() === "(") { i++; const v = sum(); if (peek() !== ")") throw new Error("missing )"); i++; return v; } if (peek() === "-") { i++; return -atom(); } if (peek() === "+") { i++; return atom(); } return num(); };
  const pow = () => { const b = atom(); if (peek() === "^") { i++; return Math.pow(b, pow()); } return b; };
  const prod = () => { let v = pow(); while (peek() === "*" || peek() === "/" || peek() === "%") { const o = s[i++]; const n = pow(); v = o === "*" ? v * n : o === "/" ? v / n : v % n; } return v; };
  const sum = () => { let v = prod(); while (peek() === "+" || peek() === "-") { const o = s[i++]; const n = prod(); v = o === "+" ? v + n : v - n; } return v; };
  const out = sum();
  if (i < s.length) throw new Error("unexpected " + s[i]);
  return out;
}

const PRIVATE = /^(localhost|.*\.local|.*\.internal|0\.0\.0\.0|127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.|\[?::1\]?$|\[?f[cd][0-9a-f]{2}:)/i;
async function runTool(name, args) {
  try {
    if (name === "calculator") return String(calc(args.expression));
    if (name === "fetch_url") {
      const u = new URL(String(args.url));
      if (!/^https?:$/.test(u.protocol) || PRIVATE.test(u.hostname)) return "error: only public http(s) addresses are allowed";
      const res = await fetch(u, { redirect: "manual", signal: AbortSignal.timeout(8000) });
      if (res.status >= 300 && res.status < 400) return "error: that address redirects to " + (res.headers.get("location") || "somewhere else") + ". Fetch the final address instead.";
      return (await res.text()).slice(0, 8000) || "(empty page)";
    }
    return "error: unknown tool " + name;
  } catch (e) { return "error: " + (e && e.message ? e.message : e); }
}

async function callModel(env, messages) {
  const key = env[KEY_ENV] || "";
  const base = env[KEY_ENV.replace(/_API_KEY$/, "") + "_BASE_URL"] || BASE_URL;
  const headers = { "content-type": "application/json" };
  let url, body;
  if (ANTHROPIC) {
    headers["x-api-key"] = key; headers["anthropic-version"] = "2023-06-01";
    url = base + "/messages"; body = { model: MODEL, max_tokens: MAX_TOKENS, system: SYSTEM, messages, ...(TOOLS.length ? { tools: TOOLS } : {}) };
  } else {
    if (key) headers.authorization = "Bearer " + key;
    url = base + "/chat/completions";
    body = { model: MODEL, max_tokens: MAX_TOKENS, messages: [{ role: "system", content: SYSTEM }, ...messages], ...(TOOLS.length ? { tools: TOOLS.map((t) => ({ type: "function", function: { name: t.name, description: t.description, parameters: t.input_schema } })) } : {}) };
  }
  const res = await fetch(url, { method: "POST", headers, body: JSON.stringify(body), signal: AbortSignal.timeout(60000) });
  const text = await res.text();
  if (!res.ok) throw new Error("model call failed: HTTP " + res.status + " " + text.slice(0, 300));
  return JSON.parse(text);
}

export async function runAgent(task, env) {
  const messages = [{ role: "user", content: String(task) }];
  let tokens = 0;
  for (let turn = 1; turn <= MAX_TURNS; turn++) {
    if (tokens > TOKEN_BUDGET) return { answer: "[stopped: token budget reached]", tokens };
    const d = await callModel(env, messages);
    let text, calls;
    if (ANTHROPIC) {
      tokens += (d.usage?.input_tokens || 0) + (d.usage?.output_tokens || 0);
      messages.push({ role: "assistant", content: d.content });
      text = d.content.filter((b) => b.type === "text").map((b) => b.text).join("");
      calls = d.content.filter((b) => b.type === "tool_use").map((b) => ({ id: b.id, name: b.name, args: b.input || {} }));
    } else {
      tokens += (d.usage?.prompt_tokens || 0) + (d.usage?.completion_tokens || 0);
      const m = d.choices[0].message; messages.push(m); text = m.content || "";
      calls = (m.tool_calls || []).map((c) => { let a = {}; try { a = JSON.parse(c.function.arguments || "{}"); } catch {} return { id: c.id, name: c.function.name, args: a }; });
    }
    if (!calls.length) return { answer: text.trim(), tokens };
    const outs = await Promise.all(calls.map((c) => runTool(c.name, c.args)));
    if (ANTHROPIC) messages.push({ role: "user", content: calls.map((c, i) => ({ type: "tool_result", tool_use_id: c.id, content: outs[i] })) });
    else calls.forEach((c, i) => messages.push({ role: "tool", tool_call_id: c.id, content: outs[i] }));
  }
  return { answer: "[stopped: reached " + MAX_TURNS + " turns]", tokens };
}

const json = (o, status = 200) => new Response(JSON.stringify(o), { status, headers: { "content-type": "application/json" } });
const same = (a, b) => { if (a.length !== b.length) return false; let d = 0; for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i); return d === 0; };

export async function handle(request, env) {
  const url = new URL(request.url);
  if (url.pathname.endsWith("/health")) return json({ ok: true });
  const token = env.AGENT_API_TOKEN || "";
  if (!token) return json({ error: "AGENT_API_TOKEN is not set, so the agent refuses to run" }, 500);
  if (!same(request.headers.get("authorization") || "", "Bearer " + token)) return json({ error: "unauthorized" }, 401);
  if (request.method !== "POST") return json({ error: "POST a JSON body like {\"task\": \"...\"}" }, 405);
  let body; try { body = await request.json(); } catch { return json({ error: "the body must be JSON" }, 400); }
  if (!body || typeof body.task !== "string" || !body.task.trim()) return json({ error: "send {\"task\": \"...\"}" }, 400);
  if (body.task.length > 20000) return json({ error: "task is too long (20000 characters at most)" }, 413);
  try { return json(await runAgent(body.task, env)); } catch (e) { return json({ error: String(e && e.message ? e.message : e) }, 502); }
}
